        '# NEON: a dark design system in the spirit of neon signs. Yellow, cyan and\n# pink on a near-black night, a drifting picture behind the page, a glowing\n# border that turns around the modal.\n#\n# The whole look is this file; neon_ui has no theme code. Values refer to\n# each other (`\$colors.primary`, `\$neon.cyan`), so a theme that `extends:\n# neon` and changes one color changes everything built from it.\n#\n# An app imports it with `spring.config.import: resources:themes/neon.yml`\n# and shows it with `spring.flutter.theme.active: neon`.\nspring:\n  flutter:\n    theme:\n      themes:\n        neon:\n          brightness: dark\n          seed-color: \$colors.primary\n\n          # ------------------------------------------------------ colors\n          colors:\n            primary: \$neon.yellow\n            on-primary: \'#0A0C12\'\n            primary-container: { color: \$colors.primary, mix: { with: black, amount: 78% } }\n            on-primary-container: \$colors.primary\n            secondary: \$neon.cyan\n            on-secondary: \'#0A0C12\'\n            tertiary: \$neon.pink\n            on-tertiary: \'#0A0C12\'\n            error: \'#FF5C7A\'\n            on-error: \'#0A0C12\'\n            surface: \'#0D1017\'\n            on-surface: \'#E4E7EE\'\n            on-surface-variant: \'#8B91A1\'\n            surface-container-lowest: \'#090B10\'\n            surface-container-low: \'#10131B\'\n            surface-container: \'#141822\'\n            surface-container-high: \'#1A1E29\'\n            surface-container-highest: \'#222733\'\n            outline: \'#343A48\'\n            outline-variant: \'#232834\'\n\n          # --------------------------------------------------- typography\n          # Space Grotesk for headings, JetBrains Mono for the rest (the\n          # fonts are in this package: the family is packages/neon_ui/...).\n          typography:\n            font-family: packages/neon_ui/JetBrains Mono\n            defaults: { letter-spacing: 0.2 }\n            display: { font-family: packages/neon_ui/Space Grotesk, weight: bold, letter-spacing: 4 }\n            headline: { font-family: packages/neon_ui/Space Grotesk, weight: bold, letter-spacing: 2 }\n            title: { font-family: packages/neon_ui/Space Grotesk, weight: 600, letter-spacing: 1.2 }\n            title-large: { font-family: packages/neon_ui/Space Grotesk, weight: bold, size: 20, letter-spacing: 1.6 }\n            display-small: { size: 36 }\n            headline-small: { size: 24 }\n            body-large: { size: 14, height: 1.4 }\n            body-medium: { size: 13, height: 1.45 }\n            body-small: { size: 12, height: 1.4 }\n            label: { font-family: packages/neon_ui/JetBrains Mono, weight: 600, letter-spacing: 1.4 }\n            label-large: { size: 13 }\n            label-medium: { size: 12 }\n            label-small: { size: 10, weight: 600, letter-spacing: 1.6 }\n            code: { font-family: packages/neon_ui/JetBrains Mono, size: 12, height: 1.5 }\n          shape: { extra-small: 2, small: 3, medium: 4, large: 4 }\n          spacing: { xs: 4, s: 8, m: 16, l: 24, xl: 32 }\n\n          # ------------------------------------------------------ tokens\n          # Values of our own. Groups nest, lists and durations work, and a\n          # color can be made from another one.\n          tokens:\n            neon:\n              # The palette. The roles above point at it, not the other way.\n              yellow: \'#F2E35B\'\n              cyan: \'#4FD8E8\'\n              pink: \'#F0508C\'\n              lavender: \'#A89BF5\'\n              green: \'#7BE495\'\n              # The splash\'s colors: a hot red for the loader and the\n              # edges, and the deep blue of its panels.\n              red: \'#FF2A55\'\n              navy: \'#060B1E\'\n              # The accent of the page: the logo, the panel mark, the glow.\n              accent: \$colors.primary\n              glow: { color: \$neon.accent, alpha: 35% }\n              # Surfaces.\n              panel: \'#CC0E1119\'\n              panel-border: { color: white, alpha: 15% }\n              code: \'#E60A0C12\'\n              input-fill: \'#B30A0C12\'\n              # A tone of a badge and its soft fill (the old badgeAlpha).\n              tone:\n                accent: \$neon.accent\n                cyan: \$neon.cyan\n                pink: \$neon.pink\n                lavender: \$neon.lavender\n                green: \$neon.green\n              tone-soft:\n                accent: { color: \$neon.accent, alpha: 12% }\n                cyan: { color: \$neon.cyan, alpha: 12% }\n                pink: { color: \$neon.pink, alpha: 12% }\n                lavender: { color: \$neon.lavender, alpha: 12% }\n                green: { color: \$neon.green, alpha: 12% }\n              # Sizes.\n              radius: \$shape.extra-small\n              border-width: 1\n              accent-width: 3\n              accent-height: 12\n              label-gap: 6\n              logo-size: 34\n              logo-shift: 1.6\n              logo-layer: { color: \$neon.pink, alpha: 70% }\n              logo-layer-b: { color: \$neon.cyan, alpha: 70% }\n              glow-blur: 18\n              grip-width: 48\n              # The modal: a group, no JSON in a string. The border turns\n              # (animations.border-spin) through these colors.\n              modal:\n                width: 460\n                barrier: transparent\n                border:\n                  width: 1\n                  glow: 8\n                  glow-alpha: 0.6\n                  colors: [\$neon.accent, \$neon.cyan, \$neon.pink, \$neon.lavender]\n            # The log panel\'s colors, like the console of Spring Boot.\n            logs:\n              text: \'#D7DAE2\'\n              faint: \'#6C7282\'\n              info: \'#4FD1A0\'\n              warn: \'#F2C94C\'\n              error: \'#FF5C7A\'\n              pid: \'#C77DFF\'\n              logger: \'#4FD8E8\'\n\n          # ------------------------------------------------------ styles\n          # What the widgets look like per state (ThemeStates). Precedence:\n          # disabled > error > pressed > hovered > focused > selected.\n          styles:\n            # A filled button: lighter on hover and focus.\n            neon-button:\n              height: 42\n              radius: \$shape.extra-small\n              border-width: \$neon.border-width\n              fill:\n                default: \$colors.primary\n                hovered: { color: \$colors.primary, mix: { with: white, amount: 14% } }\n                focused: { color: \$colors.primary, mix: { with: white, amount: 14% } }\n                pressed: { color: \$colors.primary, mix: { with: white, amount: 28% } }\n                disabled: { color: \$colors.primary, alpha: 40% }\n              border: { default: transparent }\n              text: { default: \$colors.on-primary, disabled: { color: \$colors.on-primary, alpha: 40% } }\n              transition: 120ms ease-out\n            # The same, outlined.\n            neon-button-outline:\n              height: 42\n              radius: \$shape.extra-small\n              border-width: \$neon.border-width\n              fill: { default: transparent, pressed: { color: \$colors.primary, alpha: 12% } }\n              border:\n                default: \$colors.outline\n                hovered: \$colors.primary\n                focused: \$colors.primary\n                pressed: \$colors.primary\n                disabled: { color: \$colors.outline, alpha: 40% }\n              text:\n                default: \$colors.on-surface\n                hovered: \$colors.primary\n                focused: \$colors.primary\n                disabled: { color: \$colors.on-surface, alpha: 40% }\n              transition: 120ms ease-out\n            # A pill that can be selected.\n            neon-chip:\n              padding: [12, 6]\n              radius: \$shape.extra-small\n              border-width: \$neon.border-width\n              border:\n                default: \$colors.outline\n                hovered: \$colors.primary\n                focused: \$colors.primary\n                selected: \$colors.primary\n                disabled: { color: \$colors.outline, alpha: 40% }\n              fill: { default: transparent, selected: { color: \$colors.primary, alpha: 12% } }\n              text:\n                default: \$colors.on-surface-variant\n                hovered: \$colors.primary\n                focused: \$colors.primary\n                selected: \$colors.primary\n                disabled: { color: \$colors.on-surface-variant, alpha: 40% }\n              transition: 120ms ease-out\n            # The frame of a text field: the border lights up on focus.\n            neon-text-field:\n              height: 42\n              padding: [12, 0]\n              radius: \$shape.extra-small\n              border-width: \$neon.border-width\n              fill: { default: \$neon.input-fill }\n              border:\n                default: \$colors.outline\n                hovered: \$colors.on-surface-variant\n                focused: \$colors.primary\n                error: \$colors.error\n                disabled: { color: \$colors.outline, alpha: 40% }\n              text: { default: \$colors.on-surface, disabled: { color: \$colors.on-surface, alpha: 40% } }\n              selection: { color: \$colors.primary, alpha: 35% }\n              transition: 120ms ease-out\n            # The grip of a resizable panel.\n            neon-resize-handle:\n              height: 16\n              thickness: 3\n              radius: \$shape.extra-small\n              color: { default: \$colors.outline, hovered: \$colors.primary, pressed: \$colors.primary }\n              transition: 120ms ease-out\n\n          # ----------------------------------------------------- loaders\n          # The neon-gate loader (NeonGateLoader, a kind of this package) is\n          # the splash of NEON: dark panels slide in from different sides and\n          # close like a gate, their edges glowing in cyan and red with a\n          # little flicker, and an angled red box in the middle fills by the\n          # real progress with its number. When the work is done the panels\n          # part the way they came (over the app, with the splash\'s\n          # `exit.reveal`). Each panel eases on its own share of a phase, so\n          # the phases are linear. `web` is the same picture in the browser\n          # before Flutter runs; it reads these keys as CSS variables.\n          loaders:\n            neon-gate:\n              kind: neon-gate\n              phases:\n                enter: { duration: \$animations.gate-enter.duration, curve: linear }\n                # The box fills by the progress, but takes 2.5 s at least.\n                fill: { progress: true, min-duration: 2.5s }\n                exit: { duration: \$animations.gate-exit.duration, curve: linear }\n              # The panels: the gate\'s two halves, the platforms over them.\n              gate:\n                color: \$neon.navy\n                panel: \'#0C1330\'\n              # Their glowing edges (glow is the blur, in logical pixels).\n              edge:\n                color: \$neon.cyan\n                accent: \$neon.red\n                width: 2\n                glow: 6\n              # The edges dim for a moment now and then, by this much.\n              flicker:\n                duration: \$animations.gate-flicker.duration\n                curve: linear\n                repeat: loop\n                dim: 0.5\n              # The loader: an angled box outlined in red, filled by the\n              # progress, with the number.\n              box:\n                color: \$neon.red\n                fill: { color: \$neon.red, alpha: 82% }\n                text: \$colors.on-surface\n                width: 420\n                height: 46\n                skew: -18\n                glow: 10\n              # The word in the box is the style `label-small`.\n              label:\n                text: LOADING\n                size: \$typography.label-small.size\n                letter-spacing: \$typography.label-small.letter-spacing\n              web: loaders/neon-gate.html\n\n          # ------------------------------------------------------ motion\n          motion:\n            durations: { fast: 120ms, medium: 250ms }\n            curves: { out: ease-out }\n          animations:\n            # The modal\'s border turns once in four seconds; with "reduce\n            # motion" it stands still.\n            border-spin: { duration: 4s, curve: linear, repeat: loop }\n            # The panels of the neon-gate splash slide in, one after the\n            # other, in this time; they part in the other.\n            gate-enter: { duration: 2s, curve: linear, repeat: none }\n            gate-exit: { duration: 1400ms, curve: linear, repeat: none }\n            # Their edges flicker: one cycle of dimming here and there.\n            gate-flicker: { duration: 2400ms, curve: linear, repeat: loop }\n            # The picture behind the page drifts slowly.\n            background-drift: { duration: 40s, curve: ease-in-out, repeat: reverse }\n\n          # --------------------------------------------------- background\n          # Under every screen (around the navigator): a color, the picture\n          # of this package (tool/neon_background.py makes it), a veil over\n          # it and the drift.\n          background:\n            color: \$colors.surface-container-lowest\n            image:\n              source: packages/neon_ui/assets/images/neon-background.jpg\n              fit: cover\n              alignment: center\n            overlay:\n              gradient: { type: linear, begin: top, end: bottom, colors: [transparent, \'#8007080D\'] }\n            animation: background-drift\n            effect: drift\n            transition: 400ms ease-out\n            # ThemeBackground.screen(\'stage\', ...) puts this over it.\n            screens:\n              stage:\n                overlay:\n                  gradient: { type: radial, begin: center, colors: [{ color: \$neon.accent, alpha: 22% }, transparent] }\n',
      ),
